static Node* Increment(Node* x)
{
    if (x->right != 0) { x = x->right; while (x->left != 0) x = x->left; }
    else { Node* y = x->parent; while (x == y->right) { x = y; y = y->parent; } if (x->right != y) x = y; }
    return x;
}
