void CTCFireheartMinigame::ProcessInput(EFireheartMinigameInput input)
{
    if (Moving)
        return;
    long x = XPos;
    long y = YPos;
    switch (input)
    {
    case FIREHEART_UP:    --y; break;
    case FIREHEART_RIGHT: ++x; break;
    case FIREHEART_DOWN:  ++y; break;
    case FIREHEART_LEFT:  --x; break;
    }
    if (x < 0)
        x = 0;
    else if (x > 3)
        x = 3;
    if (y < 0)
        y = 0;
    else if (y > 3)
        y = 3;
    SetHeroPos(x, y, false);
}

